import json, os
base="bench/results/2026-10-12/m1-ngram/replay"
for label, phase in [("off","single-agent"),("A","single-agent"),("off","single-mem"),("A","single-mem")]:
    p=f"{base}/{label}-{'greedy'} /requests.jsonl"
    print(f"--- {label}/{phase} (sha map for fg) ---")
    rows={json.loads(l)["id"]:json.loads(l)["out_sha256"] for l in open(p) if l.strip()}
    for k in sorted(rows)[:8]:
        print("  ", k, rows[k][:16])
    print()
# cross-arm identity in single phases
print("=== Cross-arm out_sha256 identity (fg, same id) ===")
off={}
for l in open(f"{base}/off-greedy/requests.jsonl") if False else [None]: pass
# load both single-agent and single-mem
def load(label,phase):
    d=f"{base}/{label}-greedy"
    rs=[json.loads(l) for l in open(f"{d}/requests.jsonl") if l.strip()]
    return { (r["phase"],r["id"]): r["out_sha256"] for r in rs if r.get("out_sha256") }
for ph in ["single-agent","single-mem"]:
    a=load("A",ph); offm=load("off",ph)
    keys=a.keys()&offm.keys()
    same=sum(1 for k in keys if a[k]==offm[k])
    print(f"{ph}: shared={len(keys)} identical={same} diff={len(keys)-same}")
    for k in keys:
        if a[k]!=offm[k]:
            print("   DIFF",k,"A=",a[k][:16],"off=",offm[k][:16])
EOF
python3 /tmp/identity.py

